let result = "miss";
if (power <= 10 || Math.abs(angle) > 75) {
  result = "miss";                               // miss zone: too soft or angle beyond 75°
} else if (Math.abs(angle) > 55 || power > 95) {
  result = Math.random() < 0.6 ? "miss" : "save"; // risk zone: 60% go wide
} else {
  const saveChance = 0.25 + Math.abs(angle) / 200; // sweet spot: sharper angles get saved more
  result = Math.random() < saveChance ? "save" : "goal";
}
